sp_widget.client_script:
function($scope) {
  var c = this;
  c.form = {};
  c.submitted = false;
  c.submitting = false;
  c.error = null;
  c.stores = [];

  c.server.get({ action: 'get_stores' }).then(function(response) {
    c.stores = response.data.stores || [];
  });

  c.submit = function() {
    c.error = null;
    c.submitting = true;
    c.server.get({
      action: 'create_complaint',
      order_number: c.form.order_number,
      complaint_type: c.form.complaint_type,
      order_value: c.form.order_value,
      dark_store: c.form.dark_store,
      description: c.form.description,
      contact_phone: c.form.contact_phone
    }).then(function(response) {
      c.submitting = false;
      if (response.data.success) {
        c.result = response.data.result;
        c.submitted = true;
      } else {
        c.error = response.data.error || 'Something went wrong. Please try again.';
      }
    }, function() {
      c.submitting = false;
      c.error = 'Could not reach the server. Please try again.';
    });
  };

  c.reset = function() {
    c.form = {};
    c.submitted = false;
    c.error = null;
  };
}

sp_widget.script:
(function() {
  if (input) {
    if (input.action === 'get_stores') {
      var storeGr = new GlideRecord('x_2145749_qc_dark_store');
      storeGr.addQuery('status', 'active');
      storeGr.orderBy('store_name');
      storeGr.setLimit(200);
      storeGr.query();
      var stores = [];
      while (storeGr.next()) {
        stores.push({ sys_id: storeGr.getUniqueValue() + '', store_name: storeGr.getValue('store_name') + '' });
      }
      data.stores = stores;
      return;
    }

    if (input.action === 'create_complaint') {
      if (!input.order_number || !input.complaint_type || !input.description) {
        data.success = false;
        data.error = 'Order number, issue type, and description are required.';
        return;
      }
      var gr = new GlideRecord('sn_customerservice_case');
      gr.initialize();
      gr.setValue('short_description', input.complaint_type + ' - Order #' + input.order_number);
      gr.setValue('description', input.description);
      gr.setValue('x_2145749_qc_order_number', input.order_number);
      gr.setValue('x_2145749_qc_complaint_type', input.complaint_type);
      if (input.order_value) gr.setValue('x_2145749_qc_order_value', input.order_value);
      if (input.dark_store) gr.setValue('x_2145749_qc_dark_store', input.dark_store);
      gr.setValue('contact', gs.getUserID());

      // Priority derivation from order value (no business rule exists for this)
      var v = parseFloat(input.order_value) || 0;
      if (v >= 1000) {
        gr.setValue('priority', '1');
      } else if (v >= 300) {
        gr.setValue('priority', '2');
      } else {
        gr.setValue('priority', '3');
      }

      var sysId = gr.insert();
      if (!sysId) {
        data.success = false;
        data.error = 'Could not create your case. Please try again.';
        return;
      }
      data.success = true;
      data.result = { sys_id: sysId + '', number: gr.getValue('number') + '' };
    }
  }
})();
